source("pre.R")
pw <- jwk_oct(charToRaw("password"))
hdr <- function(tok) { if (startsWith(tok, "{")) tok else rawToChar(zujose:::b64url_decode(strsplit(tok, ".", fixed = TRUE)[[1]][1], "x", NULL)) }
T <- function(label, expr, dec = TRUE) { r <- try_(expr); cat(sprintf("%-28s", label)); if (inherits(r, "err")) cat("ERR", r$cls[1], r$msg, "\n") else { d <- if (dec) try_(jwe_decrypt(r, pw, "PBES2-HS256+A128KW", "A128CBC-HS256")); cat(substr(hdr(r), 1, 230), "| self:", if (inherits(d, "err")) paste("ERR", d$cls[1], d$msg) else "ok", "\n"); add(label = label, token = r) } }
for (v in list(1000, 1e5, 600001)) T(paste("p2c", v), jwe_encrypt("x", pw, "PBES2-HS256+A128KW", header = list(p2c = v)))
if (FALSE) for (v in list(1000, 1000L, 999, 1000.5, 1e5, 100000L, 123456, 1e6, 600000, 600001, 0, -1, NA, NA_integer_, Inf, NaN, "1000", TRUE, c(1000, 2000), list(1000)))
  T(paste("p2c", deparse(v)), jwe_encrypt("x", pw, "PBES2-HS256+A128KW", header = list(p2c = v)))
cat("check_p2c 2^32-1:", format(try_(zujose:::check_p2c(4294967295))), " 2^32:", class(try_(zujose:::check_p2c(4294967296))), "\n")
T("default (600000)", jwe_encrypt("x", pw, "PBES2-HS256+A128KW"))
T("unprotected p2c flat", jwe_encrypt("x", pw, "PBES2-HS256+A128KW", unprotected = list(p2c = 2000), format = "flattened"))
T("unprotected p2c general", jwe_encrypt("x", pw, "PBES2-HS256+A128KW", unprotected = list(p2c = 2000), format = "general"))
T("recipient p2c general", jwe_encrypt("x", list(jwe_recipient(pw, "PBES2-HS256+A128KW", header = list(p2c = 3000))), format = "general"))
T("recipient p2c flat", jwe_encrypt("x", list(jwe_recipient(pw, "PBES2-HS256+A128KW", header = list(p2c = 3000))), format = "flattened"))
T("header p2c general", jwe_encrypt("x", pw, "PBES2-HS256+A128KW", header = list(p2c = 4000), format = "general"))
T("two pbes2 shared p2c", jwe_encrypt("x", list(jwe_recipient(pw, "PBES2-HS256+A128KW"), jwe_recipient(pw, "PBES2-HS512+A256KW")), header = list(p2c = 4000), format = "general"))
T("p2c both hdr+rec", jwe_encrypt("x", list(jwe_recipient(pw, "PBES2-HS256+A128KW", header = list(p2c = 3000))), header = list(p2c = 4000), format = "general"))
T("p2c on A128KW", jwe_encrypt("x", jwk_oct(as.raw(1:16)), "A128KW", header = list(p2c = 4000)))
T("p2s given", jwe_encrypt("x", pw, "PBES2-HS256+A128KW", header = list(p2s = "AAAAAAAAAAAAAAAAAAAAAA", p2c = 1000)))
T("empty password", jwe_encrypt("x", jwk_oct(raw(0)), "PBES2-HS256+A128KW", header = list(p2c = 1000)))
flush_out("p07.json")
